INSERT INTO `KBArticle` (`articleID`, `title`, `body`, `authorID`, `approvedByID`, `status`, `visibility`, `createdAt`, `publishedAt`) VALUES
  (1, 'Resetting Your i604 Network Password', 'Step-by-step instructions for resetting your i604 domain password from the self-service portal, including what to do when the reset email does not arrive within five minutes and how to unlock an account after five failed attempts.', 7, 3, 'Published', 'Public', '2026-01-20 00:00:00', '2026-01-26 00:00:00'),
  (2, 'Connecting to the i604-Corp Wi-Fi Network', 'How to join i604-Corp on Windows, macOS, iOS and Android. Covers certificate acceptance, the difference between i604-Corp and i604-Guest, and what to do if the network does not appear in the list.', 9, 4, 'Published', 'Public', '2026-03-24 17:00:00', '2026-03-25 17:00:00'),
  (3, 'Setting Up VPN Access for Remote Work', 'Installing and configuring the FortiClient VPN profile, requesting access approval from your manager, and troubleshooting the most common connection errors.', 9, 4, 'Published', 'Public', '2026-05-19 20:00:00', '2026-05-20 20:00:00'),
  (4, 'Requesting New Hardware or a Replacement Device', 'The hardware request process at i604: what needs manager approval, expected lead times by device class, and how loaner equipment is issued while a replacement is in transit.', 5, 3, 'Published', 'Public', '2026-05-08 16:00:00', '2026-05-16 16:00:00'),
  (5, 'Outlook Will Not Sync on Mobile Devices', 'Resolution steps for the most frequent mobile mail sync failures, covering re-authentication after a password change, the modern authentication requirement, and clearing the local mail cache.', 6, 3, 'Published', 'Public', '2026-03-29 01:00:00', '2026-03-30 01:00:00'),
  (6, 'Printer Queue Stuck or Jobs Not Printing', 'Clearing a stalled print queue on Windows, restarting the print spooler service, and identifying whether the fault is local or on the shared print server.', 5, 3, 'Published', 'Public', '2026-03-02 17:00:00', '2026-03-09 17:00:00'),
  (7, 'Multi-Factor Authentication Enrolment Guide', 'How to enrol an authenticator application, what to do when a device is lost or replaced, and how to request an administrator MFA reset.', 10, 3, 'Published', 'Public', '2026-03-18 19:00:00', '2026-03-21 19:00:00'),
  (8, 'Standard Onboarding Checklist for New Hires', 'The account, hardware and access provisioning steps that must be completed before a new employee''s first day, with the responsible team for each item.', 5, 4, 'Published', 'Internal', '2026-03-26 20:00:00', '2026-03-29 20:00:00'),
  (9, 'Escalation Path for Critical Incidents', 'Defines what qualifies as a Critical incident at i604, who must be notified, expected response times, and the handover procedure outside business hours.', 3, 1, 'Published', 'Internal', '2026-01-19 16:00:00', '2026-01-22 16:00:00'),
  (10, 'Diagnosing Slow Network Performance on Floor 3', 'Internal runbook for the recurring Floor 3 latency reports: switch port checks, uplink saturation thresholds, and the known bad patch panel run identified in March.', 9, 4, 'Published', 'Internal', '2026-02-18 18:00:00', '2026-02-20 18:00:00'),
  (11, 'Decommissioning and Wiping Retired Hardware', 'The approved procedure for wiping, recording and disposing of retired i604 equipment, including the certificate of destruction requirement for devices that held customer data.', 7, 4, 'Published', 'Internal', '2026-03-26 17:00:00', '2026-04-03 17:00:00'),
  (12, 'Handling Suspected Phishing Reports', 'How to triage a reported phishing message, preserve headers for analysis, and when to escalate to a Critical security incident.', 10, NULL, 'PendingApproval', 'Internal', '2026-05-18 01:00:00', NULL),
  (13, 'Software Licence Request and Renewal Process', 'Draft covering how to request a new software licence, the annual renewal calendar, and the budget approval threshold above which finance sign-off is needed.', 8, NULL, 'Draft', 'Internal', '2026-04-03 23:00:00', NULL),
  (14, 'Legacy VPN Client Configuration (Pre-2025)', 'Superseded by the FortiClient guide. Retained for reference only while the last three site-to-site tunnels are migrated.', 9, 4, 'Archived', 'Internal', '2026-05-05 19:00:00', '2026-05-14 19:00:00');
