SET NAMES utf8mb4;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET FOREIGN_KEY_CHECKS = 0;
SET @now = NOW();

ALTER TABLE `User`             AUTO_INCREMENT = 1;
ALTER TABLE `Category`         AUTO_INCREMENT = 1;
ALTER TABLE `TechGroup`        AUTO_INCREMENT = 1;
ALTER TABLE `Resource`         AUTO_INCREMENT = 1;
ALTER TABLE `KBArticle`        AUTO_INCREMENT = 1;
ALTER TABLE `Ticket`           AUTO_INCREMENT = 1001;
ALTER TABLE `TicketComment`    AUTO_INCREMENT = 1;
ALTER TABLE `TicketDraft`      AUTO_INCREMENT = 1;
ALTER TABLE `TicketAttachment` AUTO_INCREMENT = 1;
ALTER TABLE `Attachment`       AUTO_INCREMENT = 1;
ALTER TABLE `Notification`     AUTO_INCREMENT = 1;
ALTER TABLE `AuditLog`         AUTO_INCREMENT = 1;
ALTER TABLE `PasswordResetOTP` AUTO_INCREMENT = 1;

















SET FOREIGN_KEY_CHECKS = 1;

-- Reset AUTO_INCREMENT counters above the seeded identifiers so that new
-- records created during the demonstration do not collide with this data.
ALTER TABLE `User`          AUTO_INCREMENT = 200;
ALTER TABLE `Category`      AUTO_INCREMENT = 200;
ALTER TABLE `TechGroup`     AUTO_INCREMENT = 200;
ALTER TABLE `Resource`      AUTO_INCREMENT = 500;
ALTER TABLE `KBArticle`     AUTO_INCREMENT = 200;
ALTER TABLE `Ticket`        AUTO_INCREMENT = 5000;
ALTER TABLE `TicketComment` AUTO_INCREMENT = 5000;
ALTER TABLE `TicketDraft`   AUTO_INCREMENT = 100;
ALTER TABLE `Notification`  AUTO_INCREMENT = 1000;
ALTER TABLE `AuditLog`      AUTO_INCREMENT = 5000;

-- End of demonstration seed data.
